# ---- internal attempt ownership helper ----
write('src/main/java/com/plexon/travel/internal/AttemptLedger.java', '''package com.plexon.travel.internal;\n\nimport java.util.UUID;\nimport java.util.concurrent.ConcurrentHashMap;\nimport java.util.concurrent.atomic.AtomicLong;\n\n/** O(1) ownership ledger spanning destination resolution through async teleport terminal state. */\npublic final class AttemptLedger {\n    private final AtomicLong sequence = new AtomicLong();\n    private final ConcurrentHashMap<UUID, Long> active = new ConcurrentHashMap<>();\n\n    /** Returns a positive identity, or 0 when the player already owns an active attempt. */\n    public long acquire(UUID playerId) {\n        long token = sequence.incrementAndGet();\n        return active.putIfAbsent(playerId, token) == null ? token : 0L;\n    }\n\n    public boolean owns(UUID playerId, long token) {\n        Long current = active.get(playerId);\n        return current != null && current == token;\n    }\n\n    public boolean release(UUID playerId, long token) {\n        return active.remove(playerId, token);\n    }\n\n    public boolean releaseCurrent(UUID playerId) {\n        return active.remove(playerId) != null;\n    }\n\n    public boolean isActive(UUID playerId) { return active.containsKey(playerId); }\n    public int size() { return active.size(); }\n    public void clear() { active.clear(); }\n}\n''')

# ---- destructive confirmation helper ----
write('src/main/java/com/plexon/travel/internal/DestructiveConfirmationGate.java', '''package com.plexon.travel.internal;\n\nimport java.util.HashMap;\nimport java.util.Map;\nimport java.util.Objects;\n\n/** Actor/action/resource/revision-bound, expiring and one-shot destructive confirmation gate. */\npublic final class DestructiveConfirmationGate {\n    public enum Decision { ARMED, CONFIRMED }\n\n    private final long ttlMillis;\n    private final Map<Key, Entry> armed = new HashMap<>();\n\n    public DestructiveConfirmationGate(long ttlMillis) {\n        if (ttlMillis <= 0) throw new IllegalArgumentException("ttlMillis must be positive");\n        this.ttlMillis = ttlMillis;\n    }\n\n    public synchronized Decision check(String actor, String action, String resourceId, long revision, long nowMillis) {\n        Key key = new Key(require(actor), require(action), require(resourceId));\n        Entry previous = armed.remove(key);\n        purge(nowMillis);\n        if (previous != null && previous.expiresAtMillis >= nowMillis && previous.revision == revision) {\n            return Decision.CONFIRMED;\n        }\n        armed.put(key, new Entry(revision, nowMillis + ttlMillis));\n        return Decision.ARMED;\n    }\n\n    public synchronized void invalidate(String action, String resourceId) {\n        armed.keySet().removeIf(key -> key.action.equals(action) && key.resourceId.equals(resourceId));\n    }\n\n    private void purge(long nowMillis) { armed.entrySet().removeIf(entry -> entry.getValue().expiresAtMillis < nowMillis); }\n    private static String require(String value) { return Objects.requireNonNull(value, "value").trim(); }\n    private record Key(String actor, String action, String resourceId) {}\n    private record Entry(long revision, long expiresAtMillis) {}\n}\n''')

# ---- config validator ----
write('src/main/java/com/plexon/travel/internal/TravelConfigValidator.java', '''package com.plexon.travel.internal;\n\nimport org.bukkit.configuration.ConfigurationSection;\n\nimport java.util.ArrayList;\nimport java.util.List;\nimport java.util.Locale;\nimport java.util.Set;\n\npublic final class TravelConfigValidator {\n    private TravelConfigValidator() {}\n\n    public static List<String> validate(ConfigurationSection config) {\n        List<String> errors = new ArrayList<>();\n        for (String type : List.of("spawn", "hub", "warp", "back", "admin")) {\n            number(config, "teleport." + type + ".warmup-seconds", 0, 3600, errors);\n            number(config, "teleport." + type + ".cooldown-seconds", 0, 86400, errors);\n            String feePath = type.equals("warp") ? "teleport.warp.default-fee" : "teleport." + type + ".fee";\n            number(config, feePath, 0, 1_000_000_000D, errors);\n        }\n        number(config, "teleport.movement-threshold", 0, 128, errors);\n        number(config, "safe-teleport.horizontal-radius", 0, 8, errors);\n        number(config, "safe-teleport.vertical-radius", 0, 12, errors);\n        enumeration(config, "cooldowns.mode", Set.of("PER_TYPE", "GLOBAL"), errors);\n        enumeration(config, "hub.mode", Set.of("SEPARATE", "SPAWN", "DISABLED"), errors);\n        enumeration(config, "respawn.mode", Set.of("VANILLA", "SPAWN", "HUB", "LAST_BED_OR_SPAWN"), errors);\n        return List.copyOf(errors);\n    }\n\n    private static void number(ConfigurationSection config, String path, double min, double max, List<String> errors) {\n        Object raw = config.get(path);\n        if (!(raw instanceof Number number)) { errors.add(path + " must be numeric"); return; }\n        double value = number.doubleValue();\n        if (!Double.isFinite(value) || value < min || value > max) errors.add(path + " out of range [" + min + ", " + max + "]");\n    }\n\n    private static void enumeration(ConfigurationSection config, String path, Set<String> allowed, List<String> errors) {\n        String value = config.getString(path, "").trim().toUpperCase(Locale.ROOT);\n        if (!allowed.contains(value)) errors.add(path + " must be one of " + allowed);\n    }\n}\n''')

