write('src/test/java/com/plexon/travel/AttemptLedgerTest.java', '''package com.plexon.travel;\n\nimport com.plexon.travel.internal.AttemptLedger;\nimport org.junit.jupiter.api.Test;\nimport java.util.UUID;\nimport static org.junit.jupiter.api.Assertions.*;\n\nclass AttemptLedgerTest {\n    @Test void rejectsDuplicateOwnershipUntilTerminalRelease() {\n        AttemptLedger ledger = new AttemptLedger(); UUID id = UUID.randomUUID();\n        long first = ledger.acquire(id); assertTrue(first > 0); assertEquals(0L, ledger.acquire(id));\n        assertTrue(ledger.release(id, first)); assertTrue(ledger.acquire(id) > 0);\n    }\n    @Test void staleTokenCannotReleaseNewerAttempt() {\n        AttemptLedger ledger = new AttemptLedger(); UUID id = UUID.randomUUID();\n        long first = ledger.acquire(id); assertTrue(ledger.release(id, first)); long second = ledger.acquire(id);\n        assertFalse(ledger.release(id, first)); assertTrue(ledger.owns(id, second));\n    }\n    @Test void releaseCurrentCancelsPreResolutionOwnership() {\n        AttemptLedger ledger = new AttemptLedger(); UUID id = UUID.randomUUID(); ledger.acquire(id);\n        assertTrue(ledger.releaseCurrent(id)); assertFalse(ledger.isActive(id));\n    }\n    @Test void clearDropsAllRuntimeOwnership() {\n        AttemptLedger ledger = new AttemptLedger(); ledger.acquire(UUID.randomUUID()); ledger.acquire(UUID.randomUUID());\n        assertEquals(2, ledger.size()); ledger.clear(); assertEquals(0, ledger.size());\n    }\n}\n''')
write('src/test/java/com/plexon/travel/DestructiveConfirmationGateTest.java', '''package com.plexon.travel;\n\nimport com.plexon.travel.internal.DestructiveConfirmationGate;\nimport org.junit.jupiter.api.Test;\nimport static org.junit.jupiter.api.Assertions.*;\n\nclass DestructiveConfirmationGateTest {\n    @Test void firstInvocationOnlyArms() { var g = new DestructiveConfirmationGate(1000); assertEquals(DestructiveConfirmationGate.Decision.ARMED, g.check("a","delete","w",1,10)); }\n    @Test void secondMatchingInvocationConfirmsOnce() { var g = new DestructiveConfirmationGate(1000); g.check("a","delete","w",1,10); assertEquals(DestructiveConfirmationGate.Decision.CONFIRMED, g.check("a","delete","w",1,11)); assertEquals(DestructiveConfirmationGate.Decision.ARMED, g.check("a","delete","w",1,12)); }\n    @Test void actorIsBound() { var g = new DestructiveConfirmationGate(1000); g.check("a","delete","w",1,10); assertEquals(DestructiveConfirmationGate.Decision.ARMED, g.check("b","delete","w",1,11)); }\n    @Test void revisionChangeInvalidatesConfirmation() { var g = new DestructiveConfirmationGate(1000); g.check("a","delete","w",1,10); assertEquals(DestructiveConfirmationGate.Decision.ARMED, g.check("a","delete","w",2,11)); }\n    @Test void expiryInvalidatesConfirmation() { var g = new DestructiveConfirmationGate(1000); g.check("a","delete","w",1,10); assertEquals(DestructiveConfirmationGate.Decision.ARMED, g.check("a","delete","w",1,1011)); }\n}\n''')
write('src/test/java/com/plexon/travel/TravelConfigValidatorTest.java', '''package com.plexon.travel;\n\nimport com.plexon.travel.internal.TravelConfigValidator;\nimport org.bukkit.configuration.file.YamlConfiguration;\nimport org.junit.jupiter.api.Test;\nimport static org.junit.jupiter.api.Assertions.*;\n\nclass TravelConfigValidatorTest {\n    private YamlConfiguration valid() {\n        YamlConfiguration c = new YamlConfiguration();\n        for (String type : new String[]{"spawn","hub","warp","back","admin"}) { c.set("teleport."+type+".warmup-seconds", 3); c.set("teleport."+type+".cooldown-seconds", 10); c.set(type.equals("warp") ? "teleport.warp.default-fee" : "teleport."+type+".fee", 0.0); }\n        c.set("teleport.movement-threshold", 0.01); c.set("safe-teleport.horizontal-radius", 3); c.set("safe-teleport.vertical-radius", 4); c.set("cooldowns.mode", "PER_TYPE"); c.set("hub.mode", "SEPARATE"); c.set("respawn.mode", "VANILLA"); return c;\n    }\n    @Test void acceptsDefaultShape() { assertTrue(TravelConfigValidator.validate(valid()).isEmpty()); }\n    @Test void rejectsNegativeFee() { var c=valid(); c.set("teleport.spawn.fee", -1); assertFalse(TravelConfigValidator.validate(c).isEmpty()); }\n    @Test void rejectsNonFiniteMovementThreshold() { var c=valid(); c.set("teleport.movement-threshold", Double.NaN); assertFalse(TravelConfigValidator.validate(c).isEmpty()); }\n    @Test void rejectsOutOfBoundsSafeSearch() { var c=valid(); c.set("safe-teleport.horizontal-radius", 99); assertFalse(TravelConfigValidator.validate(c).isEmpty()); }\n    @Test void rejectsUnknownModes() { var c=valid(); c.set("cooldowns.mode", "mystery"); assertFalse(TravelConfigValidator.validate(c).isEmpty()); }\n}\n''')
write('src/test/java/com/plexon/travel/Phase2SourceContractTest.java', '''package com.plexon.travel;\n\nimport org.junit.jupiter.api.Test;\nimport java.nio.file.Files;\nimport java.nio.file.Path;\nimport static org.junit.jupiter.api.Assertions.*;\n\nclass Phase2SourceContractTest {\n    private String source() throws Exception { return Files.readString(Path.of("src/main/java/com/plexon/travel/PlexonTravel.java")); }\n    @Test void duplicateAttemptIsRejectedBeforeSafeResolution() throws Exception { assertTrue(source().contains("attempts.acquire(playerId)")); assertTrue(source().contains("already pending or in progress")); }\n    @Test void executingAttemptCannotBeCancelledOutFromUnderAsyncTerminal() throws Exception { assertTrue(source().contains("if (value.executing) return false")); }\n    @Test void terminalCallbackChecksExactAttemptIdentity() throws Exception { assertTrue(source().contains("attempts.owns(id, value.attemptId)")); }\n    @Test void failedTeleportUsesSingleRefundPath() throws Exception { assertTrue(source().contains("refundOnce(value)")); assertTrue(source().contains("value.refunded")); }\n    @Test void backHistoryOnlyCommitsOnSuccessfulAsyncTeleport() throws Exception { String s=source(); assertTrue(s.indexOf("Boolean.TRUE.equals(success)") < s.indexOf("setBack(id, value.origin")); }\n    @Test void warpRenamePreservesStableId() throws Exception { assertTrue(source().contains("new Warp(old.id(), displayName")); assertTrue(source().contains("stable ID remains")); }\n    @Test void deletionUsesBoundedRevisionConfirmation() throws Exception { assertTrue(source().contains("deleteGate.check(actor, \"delete-warp\", id, current.revision()")); }\n    @Test void reloadValidatesCandidateBeforeBukkitReload() throws Exception { String s=source(); int m=s.indexOf("private void reloadValidated"); String r=s.substring(m, Math.min(s.length(), m+1000)); assertTrue(r.indexOf("TravelConfigValidator.validate(candidate)") < r.indexOf("reloadConfig()")); }\n    @Test void placeholderExpansionIsCachedApiOnly() throws Exception { String p=Files.readString(Path.of("src/main/java/com/plexon/travel/papi/PlexonTravelExpansion.java")); assertFalse(p.contains("java.sql")); assertFalse(p.contains("Files.")); assertTrue(p.contains("api.warps().size()")); }\n    @Test void candidateVersionIsRc1() throws Exception { assertTrue(Files.readString(Path.of("pom.xml")).contains("<version>2.0.0-rc.1</version>")); }\n}\n''')

