summary_step = '''      - name: Write test summary\n        shell: bash\n        run: |\n          python3 - <<'PY'\n          import glob, xml.etree.ElementTree as ET\n          totals = dict(tests=0, failures=0, errors=0, skipped=0)\n          for path in glob.glob('target/surefire-reports/TEST-*.xml'):\n              root = ET.parse(path).getroot()\n              for key in totals: totals[key] += int(root.attrib.get(key, 0))\n          text = f"{totals['tests']} executed / {totals['failures']} failures / {totals['errors']} errors / {totals['skipped']} skipped\\n"\n          open('TEST_SUMMARY.txt','w').write(text)\n          print(text, end='')\n          PY\n      - name: Write provenance\n        shell: bash\n        run: |\n          {\n            echo 'repository=ZpkDxGames/PlexonTravel'\n            echo "source_sha=$GITHUB_SHA"\n            echo 'version=2.0.0-rc.1'\n            echo 'java=25'\n            echo 'class_major=69'\n            echo 'plexoncore=2.0.4'\n            echo 'plexoncore_sha256=61d625a717da9f46ee9231e1970d84b4c317ae12cf4090cdf7c9d39b6a1a9baf'\n            echo 'rollback_tag=v1.0.1'\n            echo 'rollback_sha=772188d55c694deea0bc5ae0bdce0898513499e5'\n          } > PROVENANCE.txt\n'''
build = '''name: Build\n\non:\n  push:\n    branches: ['**']\n  pull_request:\n\npermissions:\n  contents: read\n\njobs:\n  verify:\n    runs-on: ubuntu-24.04\n    steps:\n      - uses: actions/checkout@v4\n      - uses: actions/setup-java@v5\n        with:\n          distribution: temurin\n          java-version: '25'\n          cache: maven\n      - name: Provision exact PlexonCore 2.0.4\n        shell: bash\n        run: |\n          set -euo pipefail\n          curl -L --fail --retry 3 -o /tmp/PlexonCore-2.0.4.jar https://github.com/ZpkDxGames/PlexonCore/releases/download/v2.0.4/PlexonCore-2.0.4.jar\n          echo '61d625a717da9f46ee9231e1970d84b4c317ae12cf4090cdf7c9d39b6a1a9baf  /tmp/PlexonCore-2.0.4.jar' | sha256sum -c -\n          mvn -B -ntp org.apache.maven.plugins:maven-install-plugin:3.1.4:install-file -Dfile=/tmp/PlexonCore-2.0.4.jar -DgroupId=com.zpkdxgames -DartifactId=PlexonCore -Dversion=2.0.4 -Dpackaging=jar\n      - name: Test and package\n        run: mvn -B -ntp clean verify\n      - name: Verify installable JAR\n        run: ./scripts/verify-distribution.sh target/PlexonTravel-2.0.0-rc.1.jar\n''' + summary_step + '''      - name: Checksum\n        run: sha256sum target/PlexonTravel-2.0.0-rc.1.jar | sed 's#target/##' > SHA256SUMS.txt\n      - uses: actions/upload-artifact@v4\n        with:\n          name: PlexonTravel-2.0.0-rc.1\n          path: |\n            target/PlexonTravel-2.0.0-rc.1.jar\n            SHA256SUMS.txt\n            TEST_SUMMARY.txt\n            PROVENANCE.txt\n          if-no-files-found: error\n'''
