release = '''name: Release 2.0.0-rc.1\n\non:\n  push:\n    tags: ['v2.0.0-rc.1']\n\npermissions:\n  contents: write\n\njobs:\n  release:\n    runs-on: ubuntu-24.04\n    steps:\n      - uses: actions/checkout@v4\n      - name: Refuse to replace candidate\n        env:\n          GH_TOKEN: ${{ github.token }}\n        run: |\n          if gh release view v2.0.0-rc.1 >/dev/null 2>&1; then echo 'candidate release already exists' >&2; exit 1; fi\n      - uses: actions/setup-java@v5\n        with:\n          distribution: temurin\n          java-version: '25'\n          cache: maven\n      - name: Provision exact PlexonCore 2.0.4\n        shell: bash\n        run: |\n          set -euo pipefail\n          curl -L --fail --retry 3 -o /tmp/PlexonCore-2.0.4.jar https://github.com/ZpkDxGames/PlexonCore/releases/download/v2.0.4/PlexonCore-2.0.4.jar\n          echo '61d625a717da9f46ee9231e1970d84b4c317ae12cf4090cdf7c9d39b6a1a9baf  /tmp/PlexonCore-2.0.4.jar' | sha256sum -c -\n          mvn -B -ntp org.apache.maven.plugins:maven-install-plugin:3.1.4:install-file -Dfile=/tmp/PlexonCore-2.0.4.jar -DgroupId=com.zpkdxgames -DartifactId=PlexonCore -Dversion=2.0.4 -Dpackaging=jar\n      - name: Rebuild exact tag\n        run: mvn -B -ntp clean verify\n      - name: Verify distribution\n        run: ./scripts/verify-distribution.sh target/PlexonTravel-2.0.0-rc.1.jar\n''' + summary_step + '''      - name: Create checksum\n        run: sha256sum target/PlexonTravel-2.0.0-rc.1.jar | sed 's#target/##' > SHA256SUMS.txt\n      - name: Publish immutable prerelease\n        env:\n          GH_TOKEN: ${{ github.token }}\n        run: |\n          gh release create v2.0.0-rc.1 target/PlexonTravel-2.0.0-rc.1.jar SHA256SUMS.txt TEST_SUMMARY.txt PROVENANCE.txt --target "$GITHUB_SHA" --title 'PlexonTravel 2.0.0-rc.1' --notes-file releases/2.0.0-rc.1.md --prerelease\n'''
